import sys

# 简单素数判定：试除到 sqrt(n)，使用 6k±1 加速
def is_prime(n: int) -> bool:
    if n < 2:
        return False
    if n % 2 == 0:
        return n == 2
    if n % 3 == 0:
        return n == 3
    i = 5
    # 只检查 6k-1 与 6k+1
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

# 将偶数 m 拆为两个质数之和（构造）
def two_primes_sum(m: int):
    # 特判 m=4
    if m == 4:
        return 2, 2
    # 先尝试 2 + (m-2)
    if is_prime(m - 2):
        return 2, m - 2
    # 依次枚举奇数 p，检查 p 与 m-p 是否同时为质数
    p = 3
    while p <= m - 3:
        if is_prime(p) and is_prime(m - p):
            return p, m - p
        p += 2
    return None  # 理论上不会到达

def solve_case(n: int) -> str:
    if n < 8:
        return "-1"
    if n % 2 == 0:
        a, b = two_primes_sum(n - 4)
        return f"2 2 {a} {b}"
    else:
        a, b = two_primes_sum(n - 5)
        return f"2 3 {a} {b}"

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    t = data[0]
    idx = 1
    out = []
    for _ in range(t):
        n = data[idx]; idx += 1
        out.append(solve_case(n))
    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()
```

